import{_ as e,c as s,o as i,a3 as t}from"./chunks/framework.MI-M1z4O.js";const k=JSON.parse('{"title":"SyncETA クイックスタートガイド","description":"SyncETA デスクトップアプリケーションのインストール（1分）または Docker オンプレミスサーバーの起動により、最初のシナリオを録画して実行するためのクイックスタートガイドです。","frontmatter":{"title":"SyncETA クイックスタートガイド","description":"SyncETA デスクトップアプリケーションのインストール（1分）または Docker オンプレミスサーバーの起動により、最初のシナリオを録画して実行するためのクイックスタートガイドです。","head":[["meta",{"name":"keywords","content":"SyncETA クイックスタート, テスト自動化の開始, デスクトップアプリダウンロード, Playwright テスト, 録画および実行, Docker デプロイ"}],["meta",{"property":"og:title","content":"SyncETA クイックスタートガイド | 株式会社エムパシー (Empasy)"}],["meta",{"property":"og:description","content":"デスクトップアプリのインストールまたは Docker デプロイにより、3分で最初の Web 回帰テストを実行します。"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/quickstart"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/quickstart"}]],"sort":30},"headers":[],"relativePath":"ja/synceta/quickstart.md","filePath":"ja/synceta/quickstart.md","lastUpdated":1795293539000}'),l={name:"ja/synceta/quickstart.md"};function n(r,a,o,h,c,p){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="synceta-クイックスタートガイド" tabindex="-1">SyncETA クイックスタートガイド <a class="header-anchor" href="#synceta-クイックスタートガイド" aria-label="Permalink to “SyncETA クイックスタートガイド”">​</a></h1><p>SyncETA は 2 つの方法で開始できます。ローカルおよびステージング環境で素早くテストを体験したい場合は <strong>[方法 1: デスクトップアプリの簡単インストール]</strong> を、チーム単位の集中管理および CI/CD 連携サーバーを構築したい場合は <strong>[方法 2: Docker ベースのオンプレミス構築]</strong> を選択してください。</p><hr><h2 id="方法-1-デスクトップアプリの簡単インストール-推奨-1分で開始" tabindex="-1">方法 1: デスクトップアプリの簡単インストール（推奨 - 1分で開始） <a class="header-anchor" href="#方法-1-デスクトップアプリの簡単インストール-推奨-1分で開始" aria-label="Permalink to “方法 1: デスクトップアプリの簡単インストール（推奨 - 1分で開始）”">​</a></h2><p>デスクトップアプリは、別途サーバー構築やデータベース設定を行うことなく、OS ごとのインストーラーを実行するだけで即座に起動します。</p><h3 id="ステップ-1-インストーラーのダウンロード" tabindex="-1">ステップ 1: インストーラーのダウンロード <a class="header-anchor" href="#ステップ-1-インストーラーのダウンロード" aria-label="Permalink to “ステップ 1: インストーラーのダウンロード”">​</a></h3><p><a href="https://empasy.io/ja/download_eta.html" target="_blank" rel="noreferrer">株式会社エムパシー公式ダウンロードページ（empasy.io）</a>から、お使いの OS に合った最新の安定版ビルド（v0.0.44）をダウンロードします。</p><ul><li><strong>Windows</strong>: <code>SyncETA Setup 0.0.44.exe</code>（x64 および arm64 対応）</li><li><strong>macOS</strong>: <code>SyncETA-0.0.44-arm64.dmg</code>（Apple Silicon M シリーズ）または <code>SyncETA-0.0.44.dmg</code>（Intel）</li></ul><h3 id="ステップ-2-アプリケーションの起動" tabindex="-1">ステップ 2: アプリケーションの起動 <a class="header-anchor" href="#ステップ-2-アプリケーションの起動" aria-label="Permalink to “ステップ 2: アプリケーションの起動”">​</a></h3><p>インストール完了後、デスクトップまたはアプリケーション一覧から <strong>SyncETA</strong> を起動します。別途ログインや外部ネットワーク認証を行うことなく、ローカルモードで即座に起動します。</p><hr><h2 id="方法-2-docker-compose-ベースのオンプレミス構築-エンタープライズ" tabindex="-1">方法 2: Docker Compose ベースのオンプレミス構築（エンタープライズ） <a class="header-anchor" href="#方法-2-docker-compose-ベースのオンプレミス構築-エンタープライズ" aria-label="Permalink to “方法 2: Docker Compose ベースのオンプレミス構築（エンタープライズ）”">​</a></h2><p>社内インフラに SyncETA 中央サーバーおよび Playwright 分散実行ノードをデプロイする方法です。</p><div class="language-bash"><button title="コードをコピー" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># リポジトリのクローンおよびディレクトリの移動</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/DramaticCollaboration/SyncSeries.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SyncSeries/sync-eta</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># コンテナサービスの一括起動</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.dev.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>サービス起動後、ブラウザで <code>http://localhost:9000</code> にアクセスして Web コンソールを開きます。</p><hr><h2 id="最初のテストシナリオ録画および実行ハンズオン" tabindex="-1">最初のテストシナリオ録画および実行ハンズオン <a class="header-anchor" href="#最初のテストシナリオ録画および実行ハンズオン" aria-label="Permalink to “最初のテストシナリオ録画および実行ハンズオン”">​</a></h2><p>デスクトップアプリまたは Web コンソールの起動後、以下の 4 ステップの手順に従って最初の回帰テストを作成・実行します。</p><h3 id="ステップ-1-プロジェクト作成およびベース-url-の登録" tabindex="-1">ステップ 1: プロジェクト作成およびベース URL の登録 <a class="header-anchor" href="#ステップ-1-プロジェクト作成およびベース-url-の登録" aria-label="Permalink to “ステップ 1: プロジェクト作成およびベース URL の登録”">​</a></h3><ol><li>左側ナビゲーションで <strong>「プロジェクト」</strong> をクリックします。</li><li>右上の <strong>「新規プロジェクト」</strong> ボタンを押し、プロジェクト名（例: <code>コマースメインフロー</code>）と開始 URL（例: <code>https://shop.example.com</code> または <code>http://localhost:3000</code>）を入力します。</li></ol><h3 id="ステップ-2-ユーザーインタラクションの録画" tabindex="-1">ステップ 2: ユーザーインタラクションの録画 <a class="header-anchor" href="#ステップ-2-ユーザーインタラクションの録画" aria-label="Permalink to “ステップ 2: ユーザーインタラクションの録画”">​</a></h3><ol><li>左側メニューから <strong>「シナリオ」</strong> -&gt; <strong>「新しいシナリオ」</strong> を選択します。</li><li>対象ブラウザ（Chromium）およびビューポート（1920x1080）を指定したうえで <strong>「録画開始」</strong> をクリックします。</li><li>開かれたブラウザウィンドウでユーザー操作を実行します。 <ul><li>検索バーをクリックして検索キーワードを入力</li><li>検索実行ボタンをクリック</li><li>検索結果一覧から特定の項目をクリック</li></ul></li><li>録画制御ウィンドウで <strong>「録画終了」</strong> を押すと、シナリオが JSON/YAML フォーマットに自動正規化されて保存されます。</li></ol><h3 id="ステップ-3-検証条件-assertion-の登録" tabindex="-1">ステップ 3: 検証条件（Assertion）の登録 <a class="header-anchor" href="#ステップ-3-検証条件-assertion-の登録" aria-label="Permalink to “ステップ 3: 検証条件（Assertion）の登録”">​</a></h3><ol><li>保存されたシナリオエディターで検証対象となる最後のステップを選択します。</li><li><strong>「検証条件の追加」 -&gt; 「要素表示検証」</strong> を選択し、画面内の対象コンポーネント（例: 「詳細情報」領域または「決済ボタン」）を指定します。</li></ol><h3 id="ステップ-4-playwright-エンジン無人実行および自己修復の検証" tabindex="-1">ステップ 4: Playwright エンジン無人実行および自己修復の検証 <a class="header-anchor" href="#ステップ-4-playwright-エンジン無人実行および自己修復の検証" aria-label="Permalink to “ステップ 4: Playwright エンジン無人実行および自己修復の検証”">​</a></h3><ol><li>右上の <strong>「シナリオ実行」</strong> をクリックします。</li><li>実行モード（ヘッドレスまたは通常ブラウザ）を選択したうえで <strong>「実行」</strong> を押します。</li><li>実行完了後、ダッシュボードでステップ別の成否、所要時間、キャプチャされたスクリーンショット、および自己修復（Self-Healing）の適用履歴を確認します。</li></ol><hr><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to “次のステップ”">​</a></h2><ul><li><a href="./scenario-create">シナリオ録画およびエディター詳細ガイド</a> - 待機条件、リカバリスクリプトの設定</li><li><a href="./self-healing-and-vision">自己修復 &amp; ビジョン分析の仕組み</a> - Vision-LLM ベースのセレクター修復メカニズム</li><li><a href="./dataset">データセット管理</a> - Excel を活用した大量パラメーターテスト</li><li><a href="./mcp-and-cicd">MCP プロトコルおよび CI/CD 連携</a> - GitHub Actions および Jenkins パイプライン連携</li></ul>`,29)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
